import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {
  // 1) Entradas y validaciones
  const active_energy_consumption = Number(
    input?.tsl_wo_work_order_attribute?.active_energy_consumption ?? 0
  );

  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  if (!billingItemCode || String(billingItemCode).trim() === '' || billingItemCode === 'null') {
    return {
      ...input,
      result: {
        rule_description: 'parameter_billingItem_code for rule Contribucion not found',
        status: 'ERROR',
      },
    };
  }

  const billingItems =
    input?.tsl_wo_work_order_attribute?.billing_items?.active_energy_billing_items ?? [];

  if (!Array.isArray(billingItems) || billingItems.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'active_energy_billing_items not found in billing_items structure',
        status: 'ERROR',
      },
    };
  }

  // 2) Buscar el billing item objetivo (ej: "contribucion")
  const targetItem = billingItems.find(
    (bi) => String(bi?.billing_item_code ?? '').trim() === String(billingItemCode).trim()
  );

  if (!targetItem) {
    return {
      ...input,
      result: {
        rule_description:
          `The parameter_billingItem_code '${billingItemCode}' could not be found in the billing concepts structure`,
        status: 'ERROR',
      },
    };
  }

  // 3) Tomar precios desde la estructura del billing item objetivo
  const rawPrices =
    targetItem?.prices_and_method?.price_structure?.graduated_pricing?.prices ?? [];

  if (!Array.isArray(rawPrices) || rawPrices.length === 0) {
    return {
      ...input,
      result: {
        rule_description: `Rate prices for '${billingItemCode}' not found in its billing item`,
        status: 'ERROR',
      },
    };
  }

  // Normalizar y ordenar por interval_low asc
  const ranges = rawPrices
    .map((p) => ({
      low: Number(p?.interval_low ?? 0),
      high:
        Number(p?.interval_high ?? 0) === 999999999 || p?.interval_high == null
          ? 999999999
          : Number(p.interval_high),
      price: Number(p?.base_price ?? 0),
    }))
    .sort((a, b) => a.low - b.low);

  // 4) Cálculo acumulativo por bloques
  let consumo_restante = active_energy_consumption;
  let costo_total = 0;
  let prevHigh = 0;

  for (const r of ranges) {
    if (consumo_restante <= 0) break;

    // Evitar solapes/huecos
    const low = Math.max(r.low, prevHigh);
    const high = r.high;

    if (high !== 999999999 && high <= low) {
      prevHigh = Math.max(prevHigh, high);
      continue;
    }

    let consumo_rango;
    if (high === 999999999) {
      consumo_rango = consumo_restante; // rango abierto
    } else {
      const ancho = Math.max(0, high - low);
      consumo_rango = Math.min(consumo_restante, ancho);
    }

    costo_total += consumo_rango * r.price;
    consumo_restante -= consumo_rango;
    prevHigh = high === 999999999 ? prevHigh + consumo_rango : high;
  }

  if (consumo_restante !== 0) {
    return {
      ...input,
      result: {
        status: 'ERROR',
        status_description: 'Consumption ranges still need to be calculated',
      },
    };
  }

  // 5) Actualizar el mismo billing item (contribucion) con el total calculado (positivo)
  targetItem.billing_item_amount = costo_total;

  // 6) Salida
  return {
    ...input,
    result: {
      total_amount: costo_total,
      status: 'OK',
      status_description:
        'Contribucion calculation completed (prices read from billing item by billingItemCode, sorted by interval_low asc)',
    },
  };
};
